const body = { criteriaSearch: { category: ["backend"], seniority: ["senior"] } };
return [1, 2, 3].map((page) => ({
  json: {
    url: `https://nofluffjobs.com/api/search/posting?region=pl&page=${page}&salaryCurrency=PLN&salaryPeriod=month&language=en`,
    body: { ...body, page },
  },
}));

const source = $('Set Source').first().json.source;
const categories = $('Get Criteria').all().map((i) => i.json.category.toLowerCase());

const out = [];
const seenRemote = new Set();
for (const item of $input.all()) {
  const postings = item.json?.postings || [];
  for (const p of postings) {
    const tiles = (p.tiles?.values || []).map((t) => String(t.value).toLowerCase());
    const haystack = `${(p.technology || "").toLowerCase()} ${tiles.join(" ")}`;
    const category = categories.find((c) => haystack.includes(c));
    if (!category) continue;

    const s = p.salary;
    let salary = null;
    if (s && (s.from || s.to)) {
      const cur = (s.currency || "").toUpperCase();
      const type = s.type ? ` (${s.type})` : "";
      if (s.from && s.to) salary = `${cur} ${Math.round(s.from)}–${Math.round(s.to)}/month${type}`;
      else if (s.to) salary = `${cur} up to ${Math.round(s.to)}/month${type}`;
      else salary = `${cur} from ${Math.round(s.from)}/month${type}`;
    }

    const fullyRemote = !!p.location?.fullyRemote;
    // NFJ duplicates a fully-remote posting once per voivodeship - keep one
    if (fullyRemote) {
      const key = `${(p.title || "").toLowerCase()}|${(p.name || "").toLowerCase()}`;
      if (seenRemote.has(key)) continue;
      seenRemote.add(key);
    }
    const cities = (p.location?.places || []).map((pl) => pl.city).filter((c) => c && c !== "Remote");
    const location = fullyRemote ? "Remote" : (cities.join(", ") || null);

    out.push({
      json: {
        title: p.title || "",
        company: p.name || null,
        url: `https://nofluffjobs.com/job/${p.url}`,
        description: "",
        source,
        salary,
        location,
        remote: fullyRemote,
        publishedAt: p.posted ? new Date(p.posted).toISOString() : null,
        category,
        rawData: { id: p.id, technology: p.technology, seniority: p.seniority, help4Ua: p.help4Ua, salary: p.salary },
      },
    });
  }
}
return out;

const err = $input.first().json;
const source = $('Set Source').first().json.source;
const msg = err.error?.message || err.error || err.message || 'Unknown error';
return [{ json: { level: 'error', message: `${$workflow.name}: ${msg}`, source } }];

const source = $('Set Source').first().json.source;
const allJobs = $input.all().map((i) => i.json);
const jobs = JSON.stringify(allJobs.map((j) => ({
  url: j.url, title: j.title, company: j.company,
  salary: j.salary, location: j.location, publishedAt: j.publishedAt,
})));
return [{ json: { allJobs, jobs, source, totalFound: allJobs.length } }];

const { allJobs, totalFound, source } = $('Collect for Check').first().json;
const r = $input.first().json;
const fresh = new Set([...(r.newUrls || []), ...(r.updatedUrls || [])]);
const newJobs = allJobs.filter((j) => fresh.has(j.url));
return [{ json: {
  newJobs,
  enrichCount: newJobs.length,
  newCount: (r.newUrls || []).length,
  updatedCount: (r.updatedUrls || []).length,
  unchangedCount: (r.unchangedUrls || []).length,
  totalFound, source,
} }];

const { newJobs, source } = $('Filter New').first().json;
return newJobs.map((j) => {
  const slug = (j.url.split('/job/')[1] || '').trim();
  return { json: { ...j, detailUrl: `https://nofluffjobs.com/api/posting/${slug}`, source } };
});

const jobsIn = $('Split Jobs').all().map((i) => i.json);
const resp = $input.all().map((i) => i.json);
const source = $('Filter New').first().json.source;

const stripHtml = (s) => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ')
  .trim();

const compose = (d) => {
  if (!d || typeof d !== 'object') return '';
  const parts = [];
  const tasks = d.specs && d.specs.dailyTasks;
  if (Array.isArray(tasks) && tasks.length) {
    parts.push('Daily tasks:\n' + tasks.map((t) => '- ' + stripHtml(t)).join('\n'));
  }
  const reqDesc = stripHtml(d.requirements && d.requirements.description);
  if (reqDesc) parts.push('Requirements:\n' + reqDesc);
  const musts = ((d.requirements && d.requirements.musts) || []).map((m) => m.value).filter(Boolean);
  if (musts.length) parts.push('Must have: ' + musts.join(', '));
  const nices = ((d.requirements && d.requirements.nices) || []).map((m) => m.value).filter(Boolean);
  if (nices.length) parts.push('Nice to have: ' + nices.join(', '));
  return parts.join('\n\n');
};

const body = jobsIn.map((j, i) => {
  const description = compose(resp[i]);
  const { detailUrl, ...job } = j;
  return { ...job, description };
});

return [{ json: { body, count: body.length, source } }];
